import{_ as e,o as r,c as a,a5 as o}from"./chunks/framework.CXroN2RO.js";const n="/study/images/compilers/source-code-and-execution.svg",m=JSON.parse('{"title":"ソースコードから実行まで — コンパイラ・リンカー・ランタイム","description":"","frontmatter":{"title":"ソースコードから実行まで — コンパイラ・リンカー・ランタイム","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"compilers","summary":"書いたプログラムが動くまでを、ソースコード、コンパイル、リンク、起動、ランタイムに分けて説明する。C++とC#の例から、JITとAOT、エラーが起きる段階も調べる。","aliases":["ソースコード","コンパイラ","コンパイル","リンカー","リンク","オブジェクトファイル","実行ファイル","ランタイム","ビルド","JIT","AOT","IL","機械語"],"verification":"ClangとMicrosoftのC++・.NETの公式資料に照合（2026-11-07）"}},"headers":[],"relativePath":"compilers/source-code-and-execution.md","filePath":"compilers/source-code-and-execution.md"}'),s={name:"compilers/source-code-and-execution.md"};function i(l,t,d,c,h,u){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="ソースコードから実行まで-—-コンパイラ・リンカー・ランタイム" tabindex="-1">ソースコードから実行まで — コンパイラ・リンカー・ランタイム <a class="header-anchor" href="#ソースコードから実行まで-—-コンパイラ・リンカー・ランタイム" aria-label="Permalink to &quot;ソースコードから実行まで — コンパイラ・リンカー・ランタイム&quot;">​</a></h1><p>ゲームのソースを書き換えたあとは、ソースを翻訳し、必要な部品をそろえて、プログラムを起動します。ソースを書く段階、ビルドする段階、実行する段階を分けて考えると、どの段階の結果を見ているかが分かります。<a href="/study/tools/build/what-is-build.html">ビルドの基本</a></p><h2 id="書くための表現と、cpuが実行する命令" tabindex="-1">書くための表現と、CPUが実行する命令 <a class="header-anchor" href="#書くための表現と、cpuが実行する命令" aria-label="Permalink to &quot;書くための表現と、CPUが実行する命令&quot;">​</a></h2><p>人がC++やC#などで書くプログラムを<strong>ソースコード</strong>と呼びます。一般的にはテキストファイルに保存し、エディターで編集します。CPUが実行する<strong>機械語</strong>は、対象のCPUの命令を符号化したものです。例えばx86-64向けの機械語とAArch64向けの機械語は、命令の形式が異なります。<a href="/study/hardware/cpu/instruction-execution.html">CPUの命令実行</a></p><p><strong>コンパイラー</strong>は、言語の規則を調べ、ソースコードを別の表現へ翻訳するプログラムです。出力は機械語を含むオブジェクトファイルの場合も、後の処理で使う中間表現の場合もあります。ソースを読み、型などを確かめる内部の処理は、詳しい記事で扱います。<a href="https://clang.llvm.org/docs/CommandGuide/clang.html#description" target="_blank" rel="noreferrer">Clangの処理段階</a> · <a href="/study/compilers/tokens-ast-and-type-checking.html">トークン・AST・型検査</a></p><h2 id="c-の小さなプログラムを作る場合" tabindex="-1">C++の小さなプログラムを作る場合 <a class="header-anchor" href="#c-の小さなプログラムを作る場合" aria-label="Permalink to &quot;C++の小さなプログラムを作る場合&quot;">​</a></h2><p>一般的なネイティブのC++アプリでは、次のように考えられます。ここで<strong>ネイティブコード</strong>は、そのCPUが実行する機械語を指します。<a href="https://clang.llvm.org/docs/Toolchain.html" target="_blank" rel="noreferrer">Clangのツールチェーン</a></p><table tabindex="0"><thead><tr><th>段階</th><th>作るもの・すること</th></tr></thead><tbody><tr><td>ソースを編集する</td><td><code>main.cpp</code>などに処理を書く。使いたい関数の宣言をヘッダーから取り込むこともある。</td></tr><tr><td>コンパイルする</td><td>ソースを調べ、機械語や他の部品への参照を持つ<strong>オブジェクトファイル</strong>を作る。MSVCでは<code>.obj</code>が一例。</td></tr><tr><td>リンクする</td><td><strong>リンカー</strong>が複数のオブジェクトファイルやライブラリを組み合わせ、参照先を結び付けて実行ファイルなどを作る。</td></tr><tr><td>起動する</td><td>OSなどが実行に必要な準備を行い、CPUが命令を実行する。</td></tr></tbody></table><p>コンパイラーのコマンド一回でコンパイルとリンクを続けて行う構成もあります。操作するコマンドの数と、内部の仕事の数は一致するとは限りません。<a href="https://clang.llvm.org/docs/CommandGuide/clang.html#description" target="_blank" rel="noreferrer">Clangのコンパイラードライバー</a> · <a href="/study/os/process-startup.html">実行ファイルを起動する流れ</a></p><figure class="study-figure"><img src="'+n+'" alt="C++ではソースをコンパイルしてオブジェクトファイルを作り、リンクしてネイティブの実行ファイルにする。C#のJIT利用例ではソースからILを作り、実行時にJITが機械語へ変換する。" width="760" height="430" loading="lazy"><figcaption>代表的な二つの経路です。前処理や最適化などの細かな段階は省いています。<a href="/study/images/compilers/source-code-and-execution.svg" target="_blank" rel="noopener noreferrer">翻訳と実行の図を拡大</a></figcaption></figure><h2 id="実行中の処理を支えるランタイム" tabindex="-1">実行中の処理を支えるランタイム <a class="header-anchor" href="#実行中の処理を支えるランタイム" aria-label="Permalink to &quot;実行中の処理を支えるランタイム&quot;">​</a></h2><p><strong>ランタイム</strong>は、プログラムの実行を支えるソフトウェアを指す言葉です。C++のMSVCでは、Cランタイムライブラリ（CRT）が起動や終了、メモリ確保、ファイル入出力などを支えます。ライブラリを実行ファイルに取り込む構成も、DLLとして利用する構成もあります。<a href="https://learn.microsoft.com/en-us/cpp/c-runtime-library/crt-library-features?view=msvc-170" target="_blank" rel="noreferrer">MicrosoftのCRTとライブラリ構成</a></p><p>C#を.NETで使う場合には、.NETランタイムがコードの実行やメモリ管理などを担当します。<strong>ランタイム</strong>というソフトウェアの名前と、「実行時にエラーが起きた」という<strong>時点</strong>の意味を、文脈から読み分けます。<a href="https://learn.microsoft.com/en-us/dotnet/core/introduction" target="_blank" rel="noreferrer">Microsoftの.NETの構成</a></p><h2 id="c-のil、jit、aot" tabindex="-1">C#のIL、JIT、AOT <a class="header-anchor" href="#c-のil、jit、aot" aria-label="Permalink to &quot;C#のIL、JIT、AOT&quot;">​</a></h2><p>C#の一般的な.NETのビルドでは、コンパイラーが**IL（中間言語）**と型などの情報を生成します。<strong>JIT（Just-In-Time）コンパイル</strong>を使う構成では、実行時に必要なILを対象CPUの機械語へ変換します。ソースからILへ変換する段階もコンパイルです。<a href="https://learn.microsoft.com/en-us/dotnet/standard/managed-execution-process" target="_blank" rel="noreferrer">Microsoftのマネージド実行の流れ</a></p><p><strong>AOT（Ahead-Of-Time）コンパイル</strong>は、実行前に機械語などへの変換を済ませる方式です。.NETのNative AOTでは公開時にILをネイティブコードへ変換し、実行時のJITを使わずに動くアプリを作ります。UnityのIL2CPPも、ILをC++へ変換してネイティブビルドにつなぐ別の経路です。<a href="https://learn.microsoft.com/en-us/dotnet/core/deploying/native-aot/" target="_blank" rel="noreferrer">MicrosoftのNative AOT</a> · <a href="/study/languages/csharp/il2cpp.html">UnityとIL2CPP</a></p><p><strong>インタープリター</strong>は、プログラムや中間表現を読みながら、その意味に従って処理を進める実行方式です。同じ言語でも実装や設定によってコンパイル、JIT、インタープリターを組み合わせられます。例えば.NETのMonoでは、インタープリターとAOTを組み合わせる構成もあります。言語名に加え、対象の実行環境を確認します。<a href="https://learn.microsoft.com/en-us/dotnet/maui/macios/interpreter?view=net-maui-10.0" target="_blank" rel="noreferrer">Microsoftの.NET MAUIとMonoインタープリター</a></p><h2 id="エラーが出た段階を読む" tabindex="-1">エラーが出た段階を読む <a class="header-anchor" href="#エラーが出た段階を読む" aria-label="Permalink to &quot;エラーが出た段階を読む&quot;">​</a></h2><table tabindex="0"><thead><tr><th>段階</th><th>例</th><th>最初に見るもの</th></tr></thead><tbody><tr><td>コンパイル</td><td>存在しない変数名を使った。型に合わない操作を書いた。</td><td>診断に示されたソースの位置と、名前・型の説明。</td></tr><tr><td>リンク</td><td>C++で宣言した関数の実装を、リンクする入力に含めていない。</td><td>関数の定義と、リンク対象のオブジェクト・ライブラリ。</td></tr><tr><td>実行</td><td>ファイルを開く処理が失敗した。処理中に例外が送出された。</td><td>APIの結果、例外の情報、実行時の状態。</td></tr></tbody></table><p>ビルドが成功しても、計算した結果が意図と合うかは実行して確かめます。ビルドで止まる問題と、実行中の失敗を追う道具は、同じIDEの中でも役割が分かれます。<a href="/study/tools/build/link-errors.html">リンクエラー</a> · <a href="/study/tools/development-tools-basics.html">開発ツールの基本</a></p><h2 id="関連記事" tabindex="-1">関連記事 <a class="header-anchor" href="#関連記事" aria-label="Permalink to &quot;関連記事&quot;">​</a></h2><ul><li><a href="/study/runtime/cpp-internals/build-pipeline-journey.html">main.cppからCPU命令までの旅</a></li><li><a href="/study/runtime/cpp-internals/object-files-and-libraries.html">オブジェクトファイルとライブラリ</a></li><li><a href="/study/compilers/libraries-apis-and-sdks.html">ライブラリ・API・SDK</a></li><li><a href="/study/tools/terminal-shell-and-commands.html">ターミナルとシェル</a></li></ul>',22)])])}const f=e(s,[["render",i]]);export{m as __pageData,f as default};
